						if (Convert.ToDouble(Operators.ConcatenateObject("", new SqlCommand(("Select COUNT(*) from Entry where type=5 and doc_no=" + Conversions.ToString(Receipt.ReceiptNo)) ?? "", sqlConnection, sqlTransaction).ExecuteScalar())) > 0.0)
