								EntryGlobalId = sqlDataReader["GlobalID"].ToString();
							}
							sqlDataReader.Close();
						}
						if (string.IsNullOrEmpty(EntryGlobalId))
						{
							EntryOper.GetEntryGlobalID(ref EntryGlobalId, ref EntryNo);
