public void ConnectMQTList()
        {
            try
            {
                var Home = new Home();
                SqlCommand cmd = new SqlCommand("select * from Settingmqtt", conn);
                SqlDataAdapter da = new SqlDataAdapter(cmd);
                DataTable dt = new DataTable();
                da.Fill(dt);

                if (dt.Rows.Count == 0)
