private bool CheckMqttStat()
        {
            try
            {
                var Home = new Home();
                SqlDataAdapter da = new SqlDataAdapter(
                    "select * from Settingmqtt where is_active=1", conn);
                DataTable dt = new DataTable();
                da.Fill(dt);

                if (dt.Rows.Count > 0)
