ExecuteSqlAsync.syntax_text:
private async Task ExecuteSqlAsync(string sql, bool ignoreErrors = false)
        {
            try
            {
                EnsureOpen(_conn);
                using (var cmd = new SqlCommand(sql, _conn))
                    await cmd.ExecuteNonQueryAsync();
            }
            catch (Exception ex)
            {
                if (!ignoreErrors)
                    DXMessageBox.Show("خطأ: " + ex.Message);
            }
        }

